import{_ as e,o as s,c as r,a2 as a}from"./chunks/framework.CqdVOxXJ.js";const o="/rakkii-cars-guide/screenshots/v2/a08-team-dates.png",n="/rakkii-cars-guide/screenshots/v2/a10-bay-checklist.png",i="/rakkii-cars-guide/screenshots/v2/a09-under-repair.png",m=JSON.parse('{"title":"4. Assign and start work","description":"","frontmatter":{},"headers":[],"relativePath":"desk/job/04-start-work.md","filePath":"desk/job/04-start-work.md","lastUpdated":1794643263000}'),h={name:"desk/job/04-start-work.md"};function d(c,t,g,l,p,k){return s(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="_4-assign-and-start-work" tabindex="-1">4. Assign and start work <a class="header-anchor" href="#_4-assign-and-start-work" aria-label="Permalink to &quot;4. Assign and start work&quot;">​</a></h1><p><strong>Who:</strong> Owner or admin · <strong>Where:</strong> the job&#39;s <strong>Work</strong> tab · <strong>Status after:</strong> Under repair</p><h2 id="assign-the-technician" tabindex="-1">Assign the technician <a class="header-anchor" href="#assign-the-technician" aria-label="Permalink to &quot;Assign the technician&quot;">​</a></h2><ol><li>On the <strong>Work</strong> tab, find the <strong>Team</strong> card.</li><li>Tick the technician(s). Owners and admins are hidden; press <strong>Show owner and admin</strong> to see them. Each name shows whether they&#39;ve clocked in today.</li><li>Add a <strong>Reason for change</strong> if you like, then press <strong>Save technicians</strong>.</li></ol><p>Every change is kept in <strong>Assignment history</strong>.</p><p><img src="'+o+'" alt="Team and Dates cards"></p><h2 id="give-the-technician-a-checklist" tabindex="-1">Give the technician a checklist <a class="header-anchor" href="#give-the-technician-a-checklist" aria-label="Permalink to &quot;Give the technician a checklist&quot;">​</a></h2><ol><li>Find the <strong>Bay checklist</strong> card.</li><li>Choose a <strong>Template</strong> and press <strong>Apply template</strong>, or type steps in <strong>New step</strong> and press <strong>Add step</strong>.</li></ol><p>The technician ticks these as they work.</p><p><img src="'+n+'" alt="Bay checklist with two steps"></p><h2 id="start-work" tabindex="-1">Start work <a class="header-anchor" href="#start-work" aria-label="Permalink to &quot;Start work&quot;">​</a></h2><p>Press <strong>Approve and start work</strong> on the <strong>Quote</strong> card (or <strong>Start work</strong> on a job with no quote). The status becomes <strong>Under repair</strong>, the progress card says &quot;Finish work and send to QC.&quot;, and the job appears on the technician&#39;s <strong>My jobs</strong>.</p><p><img src="'+i+'" alt="Job at Under repair; Ready for pickup is locked until the QC photos are in"></p><h2 id="dates-are-filled-in-for-you" tabindex="-1">Dates are filled in for you <a class="header-anchor" href="#dates-are-filled-in-for-you" aria-label="Permalink to &quot;Dates are filled in for you&quot;">​</a></h2><p>The <strong>Dates</strong> card records <strong>Car in</strong>, <strong>Started</strong>, <strong>Done</strong>, <strong>Car out</strong>, <strong>Billed</strong> and <strong>Paid</strong> from what happens on the job. To correct one, press <strong>Edit dates</strong>.</p><h2 id="if-something-stops-you" tabindex="-1">If something stops you <a class="header-anchor" href="#if-something-stops-you" aria-label="Permalink to &quot;If something stops you&quot;">​</a></h2><table tabindex="0"><thead><tr><th>You see</th><th>What to do</th></tr></thead><tbody><tr><td>The deposit must be paid before work</td><td>Record the deposit on <strong>Pay</strong>, or the owner types a reason to start without it.</td></tr><tr><td>Files tab asks for the usual documents</td><td>Fill the intake checklist, or open <strong>Start work without the usual documents</strong> and save a reason.</td></tr></tbody></table><p><strong>Next:</strong> <a href="/rakkii-cars-guide/desk/job/05-qc-and-ready">5. QC and ready for pickup</a></p>',18)])])}